mapper.select:
SELECT , w.enabled AS enabled FROM word w WHERE w.deleted = 0 AND w.wordbook_id = #{wordbookId}
AND w.enabled = #{enabled}
AND ( w.word LIKE CONCAT('%', #{keyword}, '%') OR w.normalized_word LIKE CONCAT('%', #{keyword}, '%') OR w.primary_definition LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY w.sequence_no ASC, w.id ASC

SELECT
    w.id AS wordId,
    w.sequence_no AS sequenceNo
FROM word w
WHERE w.deleted = 0
  AND w.enabled = 1
  AND w.wordbook_id = #{wordbookId}
  AND w.sequence_no > #{startSequenceNo}
ORDER BY w.sequence_no ASC, w.id ASC
LIMIT #{limit}
